      "DROP TABLE `events`;",
      "ALTER TABLE `__new_events` RENAME TO `events`;",
      "UPDATE sqlite_sequence SET seq = max(seq, coalesce((SELECT max(seq) FROM `__events_seq`), 0)) WHERE name = 'events';",
      "DROP TABLE `__events_seq`;",
      "PRAGMA foreign_keys=ON;",
